def lcm(x, y):
    # Base case: if x is 0 or y is 0, LCM is 0
    if x == 0 or y == 0:
        return 0
    # Recursive case: LCM of x and y is (x * y) / GCD(x, y)
    else:
        return (x * y) // gcd(x, y)

# Function to calculate the greatest common divisor (GCD) of two numbers
def gcd(x, y):
    # Recursive case: GCD of x and y is the same as the GCD of y and x mod y
    if y == 0:
        return x
    else:
        return gcd(y, x % y)

